function renderTabs(){document.getElementById('client-tabs').innerHTML=tabs.map((t,i)=>`<button class="client-tab ${selected===i?'active':''}" role="tab" id="tab-${i}" aria-controls="panel-${i}" aria-selected="${selected===i}" tabindex="${selected===i?0:-1}" data-tab="${i}"><span class="tab-summary"><span class="client-logo">${icon(t.icon)}</span><span class="client-name">${t.name}<span class="client-id">${t.subtitle}</span></span></span>${i===0?'<span class="system-new-badge">جديد</span>':''}${i===2?'<span class="summary-decision-badge">قرار جديد</span>':''}<span class="tab-revenue">${t.detail}</span></button>`).join('')}
function selectTab(i,focus=false){selected=i;renderTabs();document.querySelectorAll('[data-nav]').forEach(b=>{const active=b.dataset.nav===['Overview', 'Clients', '', 'Reports', 'Archive'][i];b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});document.querySelectorAll('.tab-panel').forEach((p,n)=>p.hidden=n!==i);const tab=document.getElementById(`tab-${i}`),rail=document.getElementById('client-tabs');if(focus)tab.focus({preventScroll:true});if(rail.scrollWidth>rail.clientWidth){const a=tab.getBoundingClientRect(),b=rail.getBoundingClientRect();rail.scrollBy({left:a.left+a.width/2-b.left-b.width/2,behavior:'instant'})}}
document.getElementById('client-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)selectTab(Number(b.dataset.tab))});
document.getElementById('client-tabs').addEventListener('keydown',e=>{let i=selected;if(e.key==='ArrowLeft')i=(i+1)%tabs.length;else if(e.key==='ArrowRight')i=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();selectTab(i,true)});
