const docState={query:'',category:'all',page:1},pageSize=4;
function normalize(text){return text.normalize('NFKD').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').toLowerCase().trim()}
function matchingDocs(){const query=normalize(docState.query);return documents.filter(d=>(docState.category==='all'||d.category===docState.category)&&normalize(d.title+' '+d.category+' '+d.description).includes(query))}
function docsCard(){return `<aside class="documents-card" aria-labelledby="documents-title"><div class="documents-heading"><div class="documents-title-group"><span class="documents-mark">${icon('folder')}</span><div><h2 id="documents-title">المستندات</h2><p>المراجع والأدلة في مكان واحد</p></div></div><span class="total-badge">${number(documents.length)}</span></div><div class="document-controls"><label class="document-search"><span>${icon('search')}</span><input id="document-search" type="search" autocomplete="off" placeholder="ابحث عن مستند…" aria-label="البحث في المستندات"></label><label class="document-category"><span>التصنيف</span><select id="document-category" aria-label="تصنيف المستندات"><option value="all">جميع التصنيفات</option>${['أدلة','سياسات','نماذج','تقارير'].map(c=>`<option value="${c}">${c}</option>`).join('')}</select></label></div><div class="documents-caption"><span>اسم المستند</span><span id="document-results" role="status" aria-live="polite"></span></div><div class="document-list" id="document-list"></div><footer class="documents-footer"><span id="document-page-label"></span><nav class="document-pagination" id="document-pagination" aria-label="صفحات المستندات"></nav></footer></aside>`}
function renderDocuments(){const matches=matchingDocs(),pages=Math.max(1,Math.ceil(matches.length/pageSize));docState.page=Math.min(Math.max(1,docState.page),pages);const start=(docState.page-1)*pageSize,rows=matches.slice(start,start+pageSize);document.getElementById('document-results').textContent=matches.length?matches.length===1?'مستند واحد':matches.length===2?'مستندان':`${number(matches.length)} ${matches.length<=10?'مستندات':'مستندًا'}`:'لا توجد نتائج';document.getElementById('document-list').innerHTML=rows.length?rows.map(d=>`<button class="document-row" data-document="${d.id}" aria-label="عرض ${d.title}"><span class="document-file ${d.category==='نماذج'?'blue':d.category==='سياسات'?'sage':d.category==='تقارير'?'rose':'slate'}">${icon('file')}</span><span class="document-copy"><strong>${d.title}</strong><span><b>${d.category}</b><i aria-hidden="true">·</i>${pageCount(d.pages)}</span><time>${d.date}</time></span><span class="document-open">${icon('chevron-left')}</span></button>`).join(''):`<div class="documents-empty">${icon('search')}<strong>لم نعثر على مستندات</strong><p>جرّب كلمة أخرى أو غيّر التصنيف.</p><button data-reset-documents>مسح البحث والتصفية</button></div>`;document.getElementById('document-page-label').textContent=matches.length?`${number(start+1)}–${number(Math.min(start+pageSize,matches.length))} من ${number(matches.length)}`:'0 مستند';document.getElementById('document-pagination').innerHTML=matches.length?`<button data-document-page="${docState.page-1}" ${docState.page===1?'disabled':''} aria-label="الصفحة السابقة">${icon('chevron-right')}</button>${Array.from({length:pages},(_,i)=>`<button data-document-page="${i+1}" ${docState.page===i+1?'aria-current="page"':''} aria-label="الصفحة ${number(i+1)}">${number(i+1)}</button>`).join('')}<button data-document-page="${docState.page+1}" ${docState.page===pages?'disabled':''} aria-label="الصفحة التالية">${icon('chevron-left')}</button>`:''}
function openDocument(id){const d=documents.find(d=>d.id===Number(id));if(!d)return;showDialog(d.title,`<div class="document-preview"><div class="document-preview-meta"><span>${d.category}</span><span>${pageCount(d.pages)}</span><time>${d.date}</time></div><p>${d.description}</p><h3>محتوى المستند</h3><p>يوضح هذا المستند نطاق العمل والخطوات الرئيسية والمسؤوليات المرتبطة بها. تُراجع المعلومات مع الجهة المختصة قبل تطبيقها.</p><p class="detail-note">هذا ملخص تجريبي لمعاينة المكتبة، وليس ملفًا مؤسسيًا فعليًا.</p></div>`)}
