function mediaSpace(){const items=mediaItems.filter(item=>mediaCategory==='الكل'||item.category===mediaCategory),featured=items[0]||mediaItems[0],remaining=items.filter(item=>item.id!==featured.id);return `<section class="media-space" aria-labelledby="media-title"><header class="media-header"><div><span class="media-eyebrow">مكتبة تتجدد كل أسبوع</span><h1 id="media-title">الوسائط</h1><p>قصص وصور وفيديوهات ومقالات من داخل مساحة العمل.</p></div><label class="media-week-picker"><span>${icon('calendar')}</span><select data-media-week aria-label="اختر أسبوع الوسائط"><option ${mediaWeek==='15–21 سبتمبر 2026'?'selected':''}>15–21 سبتمبر 2026</option><option ${mediaWeek==='8–14 سبتمبر 2026'?'selected':''}>8–14 سبتمبر 2026</option><option ${mediaWeek==='1–7 سبتمبر 2026'?'selected':''}>1–7 سبتمبر 2026</option></select></label></header><div class="media-week-note"><span>${icon('refresh')}</span><span>تم تحديث هذه الصفحة لهذا الأسبوع</span><b>${number(mediaItems.length)} مواد مختارة</b></div><div class="media-filters" role="tablist" aria-label="فئات الوسائط">${mediaCategories.map(category=>`<button role="tab" aria-selected="${mediaCategory===category}" data-media-category="${category}">${category}</button>`).join('')}</div><div class="media-feature-layout"><article class="media-feature" style="--media-image:url('./assets/${featured.image||'hero-oman-desert.png'}')"><div class="media-feature-top"><span>${featured.category}</span><span>${featured.type}</span></div><div class="media-feature-copy"><p>اختيارات هذا الأسبوع</p><h2>${featured.title}</h2><span>${featured.summary}</span><button data-media-open="${featured.id}">${featured.type==='فيديو'?icon('play'):icon('arrow-up-right')} استعرض المادة</button></div></article><aside class="media-spotlight"><span class="media-spotlight-icon">${icon('sparkles')}</span><div><small>من مجتمعنا</small><h2>موهبتك تستحق أن تُروى</h2><p>شارك قصة، صورة، أو إنجازًا من فريقك في التحديث القادم.</p></div><button type="button" data-media-contribute>شارك مادة ${icon('arrow-up-right')}</button></aside></div><section class="media-stream" aria-labelledby="media-stream-title"><div class="media-stream-heading"><div><span>${icon('layers')}</span><h2 id="media-stream-title">مختارات الأسبوع</h2></div><span>${mediaWeek}</span></div><div class="media-grid">${remaining.map(item=>`<article class="media-card ${item.image?'has-media':'text-card'}"><div class="media-card-visual" ${item.image?`style="background-image:url('./assets/${item.image}')"`:''}>${item.image?`<span class="media-card-type">${item.type==='فيديو'?icon('play'):icon('image')} ${item.type}</span>`:`<span>${icon('article')}</span>`}</div><div class="media-card-copy"><span>${item.category}<small>${item.duration||item.author}</small></span><h3>${item.title}</h3><p>${item.summary}</p><button data-media-open="${item.id}">استعرض ${icon('chevron-left')}</button></div></article>`).join('')}</div></section></section>`}
const mediaBookPages=[
 {title:'مقدمة الدليل',kicker:'البداية',text:'هذا كتاب تجريبي داخل مساحة الوسائط، صُمم لتجربة قراءة الملفات بأسلوب قريب من تصفح كتاب مطبوع.'},
 {title:'فكرة التجربة',kicker:'الفصل الأول',text:'نبني التجارب الواضحة من التفاصيل الصغيرة: عنوان مفهوم، إيقاع هادئ، ومسار واحد لا يربك القارئ.'},
 {title:'مساحات تشجّع المشاركة',kicker:'الفصل الثاني',text:'عندما تكون المعرفة متاحة وسهلة التصفح، تصبح مشاركة القصص والخبرات جزءًا طبيعيًا من يوم العمل.'},
 {title:'خلاصة قصيرة',kicker:'الختام',text:'المحتوى الجيد لا يحتاج ضجيجًا؛ يحتاج ترتيبًا جميلًا يمنح كل فكرة المساحة المناسبة للظهور.'}
];
let mediaBookPage=0;
function mediaBookReader(){const page=mediaBookPages[mediaBookPage];return `<section class="media-book-reader" aria-labelledby="media-book-title"><aside class="media-book-meta"><span class="media-book-icon">${icon('file')}</span><div><p>قارئ الملفات</p><h2 id="media-book-title">دليل التجربة الداخلية</h2><span>PDF · 18 صفحة</span></div><small>كتاب تجريبي لهذا الأسبوع</small></aside><div class="media-book-stage"><header><span>دليل التجربة الداخلية.pdf</span><div><button type="button" data-media-book-page="${mediaBookPage-1}" ${mediaBookPage===0?'disabled':''} aria-label="الصفحة السابقة">${icon('chevron-right')}</button><b>${number(mediaBookPage+1)} / ${number(mediaBookPages.length)}</b><button type="button" data-media-book-page="${mediaBookPage+1}" ${mediaBookPage===mediaBookPages.length-1?'disabled':''} aria-label="الصفحة التالية">${icon('chevron-left')}</button></div></header><div class="media-book-spread"><article class="media-book-page media-book-index"><span>الفهرس</span><strong>دليل التجربة<br>الداخلية</strong><ol><li class="is-active">مقدمة الدليل</li><li>فكرة التجربة</li><li>مساحات المشاركة</li><li>الخلاصة</li></ol><small>مساحة الوسائط · 2026</small></article><article class="media-book-page media-book-content"><span>${page.kicker}</span><h3>${page.title}</h3><p>${page.text}</p><i></i><i></i><i></i><footer>صفحة ${number(mediaBookPage+1)}</footer></article></div></div></section>`}
function renderMedia(){const panel=document.getElementById('panel-1');if(panel)panel.innerHTML=mediaSpace()+mediaBookReader()}
function basicHighlights(){return `<section class="news-highlights" aria-labelledby="highlights-title"><header><div><span>${icon('sparkles')}</span><div><h3 id="highlights-title">إضاءات</h3><p>روابط وفرص مختارة لك</p></div></div><small>إعلانات</small></header><div class="highlights-grid"><a href="#highlight-knowledge" data-highlight="knowledge"><span>دليل جديد</span><strong>كل ما تحتاجه لبدء أسبوعك بوضوح</strong><em>استكشف الدليل ${icon('chevron-left')}</em></a><a href="#highlight-event" data-highlight="event"><span>فعالية قادمة</span><strong>سجّل حضورك في ملتقى المعرفة</strong><em>اعرف التفاصيل ${icon('chevron-left')}</em></a></div></section>`}
const renderEventGallery=eventsGallery;eventsGallery=events=>`${highlights()}${renderEventGallery(events)}`;
function highlights(){const links=[['knowledge','دليل جديد','كل ما تحتاجه لبدء أسبوعك بوضوح','استكشف الدليل'],['event','فعالية قادمة','سجّل حضورك في ملتقى المعرفة','اعرف التفاصيل'],['service','خدمة رقمية','أنجز طلباتك من بوابة الخدمات الجديدة','انتقل للخدمة'],['story','قصة فريق','اقرأ تجربة فريق المشاريع هذا الشهر','اقرأ القصة'],['learning','جلسة قصيرة','احجز مقعدك في جلسة مهارات العرض','احجز مقعدك']];return `<section class="news-highlights" aria-labelledby="highlights-title"><header><div><span>${icon('sparkles')}</span><div><h3 id="highlights-title">إضاءات</h3><p>روابط وفرص مختارة لك</p></div></div><small>إعلانات</small></header><div class="highlights-grid" data-highlight-rail tabindex="0">${links.map(([id,label,title,action])=>`<a href="#highlight-${id}" data-highlight="${id}"><span>${label}</span><strong>${title}</strong><em>${action} ${icon('chevron-left')}</em></a>`).join('')}</div><footer class="highlights-controls"><span>اسحب لاستعراض المزيد</span><div><button type="button" data-highlight-scroll="-1" aria-label="الرابط السابق">${icon('chevron-right')}</button><button type="button" data-highlight-scroll="1" aria-label="الرابط التالي">${icon('chevron-left')}</button></div></footer></section>`}
function reportsSpace(){return `<header class="space-heading"><div><h1>التقارير والنشاط</h1><p>ملخصات العمل وأحدث التحديثات</p></div><span class="space-label">سكيفور</span></header><div class="report-layout"><article class="space-card"><div class="panel-heading"><h2>${icon('chart')}التقارير المتاحة</h2></div><div class="report-list">${documents.filter(d=>d.category==='تقارير').map(d=>`<button data-document="${d.id}"><span class="report-icon">${icon('chart')}</span><span><strong>${d.title}</strong><small>${d.date}</small></span><span>${pageCount(d.pages)}</span>${icon('chevron-left')}</button>`).join('')}</div></article><article class="space-card"><div class="panel-heading"><h2>${icon('clock')}سجل النشاط</h2></div><ol class="activity-list"><li><strong>إضافة تقرير الأداء الشهري</strong><p>فريق العمليات</p><time>منذ ساعة</time></li><li><strong>تحديث دليل استخدام الأنظمة</strong><p>إدارة تقنية المعلومات</p><time>منذ 3 ساعات</time></li><li><strong>مراجعة نموذج طلب شراء جهاز</strong><p>إدارة المشتريات</p><time>أمس</time></li></ol></article></div>`}
function archiveSpace(){return `<header class="space-heading"><div><h1>الأرشيف والمحفوظات</h1><p>إصدارات سابقة ومستندات مرجعية محفوظة</p></div><span class="space-label">ثيلو</span></header><div class="archive-layout"><article class="space-card"><div class="panel-heading"><h2>${icon('archive')}المستندات المؤرشفة</h2><span class="total-badge">4</span></div><div class="archive-list">${['تقرير النصف الأول — 2026','دليل الإجراءات — الإصدار السابق','محضر اجتماع إطلاق المشروع','خطة العمل — الربع الثاني'].map((title,i)=>`<button data-archive="${i}"><span class="archive-file">${icon('file')}</span><span><strong>${title}</strong><small>نسخة محفوظة · أغسطس 2026</small></span><span class="archive-badge">مؤرشف</span>${icon('chevron-left')}</button>`).join('')}</div></article><article class="space-card saved-card"><div class="panel-heading"><h2>${icon('folder')}مراجع محفوظة</h2></div><button data-document="6">${icon('file')}سياسة حفظ المستندات${icon('chevron-left')}</button><button data-document="9">${icon('file')}دليل إدارة المراسلات${icon('chevron-left')}</button></article></div>`}
function initializePanels(){document.getElementById('panel-0').innerHTML=`<div class="systems-layout"><div class="systems-main"><div class="systems-work-row">${inboxCard()}${requestsCard()}</div></div>${docsCard()}</div>`;document.getElementById('panel-1').innerHTML=mediaSpace();document.getElementById('panel-2').innerHTML=summarySpace();document.getElementById('panel-3').innerHTML=reportsSpace();document.getElementById('panel-4').innerHTML=archiveSpace();renderDocuments()}
host.addEventListener('input',e=>{if(e.target.id==='document-search'){docState.query=e.target.value;docState.page=1;renderDocuments()}});
host.addEventListener('change',e=>{if(e.target.id==='document-category'){docState.category=e.target.value;docState.page=1;renderDocuments()}if(e.target.matches('[data-media-week]')){mediaWeek=e.target.value;renderMedia()}});
host.addEventListener('click',e=>{
 const highlightScroll=e.target.closest('[data-highlight-scroll]');if(highlightScroll){const rail=highlightScroll.closest('.news-highlights')?.querySelector('[data-highlight-rail]');if(rail)rail.scrollBy({left:Number(highlightScroll.dataset.highlightScroll)*rail.clientWidth*.75,behavior:'smooth'});return}
 const highlight=e.target.closest('[data-highlight]');if(highlight){e.preventDefault();const content=highlight.dataset.highlight==='knowledge'?['دليل بداية الأسبوع','دليل مختصر يجمع أهم الروابط والخدمات التي تساعدك على تنظيم أسبوع العمل.']:['ملتقى المعرفة','فعالية داخلية تجمع تجارب الفرق وقصصها، مع جلسات قصيرة قابلة للحجز.'];showDialog(content[0],`<p>${content[1]}</p><p class="detail-note">رابط تجريبي من قسم إضاءات.</p>`);return}
 const mediaBookButton=e.target.closest('[data-media-book-page]');if(mediaBookButton&&!mediaBookButton.disabled){mediaBookPage=Math.max(0,Math.min(mediaBookPages.length-1,Number(mediaBookButton.dataset.mediaBookPage)));renderMedia();return}
 const mediaFilter=e.target.closest('[data-media-category]');if(mediaFilter){mediaCategory=mediaFilter.dataset.mediaCategory;renderMedia();return}
 const mediaOpen=e.target.closest('[data-media-open]');if(mediaOpen){const item=mediaItems.find(item=>item.id===Number(mediaOpen.dataset.mediaOpen));if(item)showDialog(item.title,`<div class="media-dialog"><span>${item.category} · ${item.type}</span><p class="detail-note">${item.duration||item.author||'مادة أسبوعية'}</p><p>${item.summary}</p></div>`);return}
 const mediaContribute=e.target.closest('[data-media-contribute]');if(mediaContribute){showDialog('شارك مادة',`<p class="detail-note">مجتمع الوسائط</p><p>يمكنك إرسال قصة أو صورة أو فيديو لإدراجه ضمن تحديث الأسبوع القادم.</p>`);return}
 const newsFilter=e.target.closest('[data-news-category]');if(newsFilter){newsCategory=newsFilter.dataset.newsCategory;renderSummary();return}
 const eventScroll=e.target.closest('[data-event-scroll]');if(eventScroll){const rail=eventScroll.closest('.events-gallery')?.querySelector('[data-event-rail]');if(rail)rail.scrollBy({left:Number(eventScroll.dataset.eventScroll)*rail.clientWidth*.76,behavior:'smooth'});return}
 const notification=e.target.closest('[data-notification]');if(notification){const item=notificationsData.find(n=>n.id===notification.dataset.notification);if(item)showDialog(item.title,`<p class="detail-note">${item.meta} · ${item.time}</p><p>${item.detail}</p>`);return}
 const decision=e.target.closest('[data-decision]');if(decision){const decisionId=Number(decision.dataset.decision),item=decisionsData.find(d=>d.id===decisionId);unreadDecisionIds.delete(decisionId);decision.classList.remove('is-unread');decision.querySelector('.notification-new-indicator')?.remove();if(item)showDialog(item.title,`<div class="decision-dialog"><div class="decision-dialog-meta"><span>${item.entity}</span><span>${item.date}</span><span>${number(item.pages)} صفحات</span></div><div class="pdf-preview"><header><b>PDF</b><span>${item.file}</span></header><h3>${item.title}</h3><p>${item.summary}</p><i></i><i></i><i></i><small>معاينة مرئية لملف القرار النهائي.</small></div></div>`);return}
 const summaryRequest=e.target.closest('[data-summary-request]');if(summaryRequest){const request=requestsData[Number(summaryRequest.dataset.summaryRequest)];showDialog(request[0],`<p class="detail-note">${request[1]} · ${request[2]}</p><p>طلب تجريبي يظهر في ملخص مساحة العمل تلقائيًا.</p>`);return}
 const category=e.target.closest('[data-inbox-category]');if(category){inboxCategory=category.dataset.inboxCategory;refreshInbox(category.id);return}
 const scope=e.target.closest('[data-inbox-scope]');if(scope){inboxScope=scope.dataset.inboxScope;refreshInbox(scope.id);return}
 const msg=e.target.closest('[data-message]');if(msg){const m=inboxMessages.find(m=>m.id===msg.dataset.message);inboxSelected=m.id;document.querySelectorAll('.inbox-row').forEach(row=>row.classList.toggle('is-highlighted',row.dataset.message===m.id));showDialog(m.title,`<div class="inbox-detail"><p class="detail-note">${m.sender} · ${m.age}</p><span class="inbox-badge ${m.category}">${m.category==='action'?'للإجراء':'للعلم'}</span><p>${m.description}</p><dl><div><dt>رقم الطلب</dt><dd>طلب-${digits(m.id.split('-')[1])}</dd></div><div><dt>المشروع</dt><dd>تطوير منتج جديد</dd></div></dl><p class="detail-note">رسالة تجريبية لمعاينة التصميم.</p></div>`);return}
 const doc=e.target.closest('[data-document]');if(doc){openDocument(doc.dataset.document);return}
 const page=e.target.closest('[data-document-page]');if(page&&!page.disabled){docState.page=Number(page.dataset.documentPage);renderDocuments();document.querySelector(`#document-pagination [data-document-page="${docState.page}"][aria-current]`)?.focus({preventScroll:true});return}
 if(e.target.closest('[data-reset-documents]')){docState.query='';docState.category='all';docState.page=1;document.getElementById('document-search').value='';document.getElementById('document-category').value='all';renderDocuments();document.getElementById('document-search').focus();return}
 const project=e.target.closest('[data-project]');if(project){const p=projectData[Number(project.dataset.project)];showDialog(p[0],`<p>${p[3]}</p><table class="detail-data"><tr><td>الحالة</td><td>${p[1]}</td></tr><tr><td>الإنجاز</td><td>${p[2]}</td></tr></table><p class="detail-note">مشروع تجريبي لمعاينة مساحة العمل.</p>`);return}
 const task=e.target.closest('[data-task]');if(task){const t=taskData[Number(task.dataset.task)];showDialog(t[0],`<p class="detail-note">الجهة المسؤولة: ${t[2]}<br>الموعد: ${t[1]}</p><p>متابعة المهمة ومراجعة مخرجاتها مع الفريق المعني.</p><p class="detail-note">مهمة تجريبية.</p>`);return}
 const team=e.target.closest('[data-team]');if(team){const t=teamData[Number(team.dataset.team)];showDialog(t[0],`<p>${t[1]}</p><p class="detail-note">عضو تجريبي في دليل الفريق.</p>`);return}
 const meeting=e.target.closest('[data-meeting]');if(meeting){showDialog(Number(meeting.dataset.meeting)===0?'مراجعة تقدم المشاريع':'جلسة تخطيط الأسبوع','<p>استعراض تقدم العمل ومناقشة الأولويات وتحديد مهام المتابعة.</p><p class="detail-note">موعد تجريبي غير مرتبط بتقويم خارجي.</p>');return}
 const archive=e.target.closest('[data-archive]');if(archive){showDialog(archive.querySelector('strong').textContent,'<p>نسخة مرجعية محفوظة للاطلاع على الإصدارات السابقة.</p><p class="detail-note">مستند تجريبي لمعاينة الأرشيف.</p>')}
});
host.addEventListener('keydown',e=>{const t=e.target.closest('.inbox-card [role="tab"]');if(!t||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...t.parentElement.querySelectorAll('[role="tab"]')],i=tabs.indexOf(t),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowLeft'?1:tabs.length-1))%tabs.length;e.preventDefault();tabs[next].click()});
