const profileButton=document.getElementById('profile'),profileSheet=document.getElementById('profile-sheet'),profileSheetClose=document.getElementById('profile-sheet-close');
function setProfileSheet(open){document.body.classList.toggle('profile-sheet-open',open);profileSheet.setAttribute('aria-hidden',String(!open));profileButton.setAttribute('aria-expanded',String(open));if(open)profileSheetClose.focus({preventScroll:true});else profileButton.focus({preventScroll:true});}
