const globalSearchInput=document.getElementById('global-search'),globalSearchResults=document.getElementById('global-search-results');let globalSearchMatches=[];
function globalSearchEntries(){return [...tabs.map((tab,index)=>({kind:'tab',icon:tab.icon,label:'تبويب',title:tab.name,meta:tab.subtitle,index})),...documents.map(item=>({kind:'document',icon:'file',label:'مستند',title:item.title,meta:item.category,item})),...inboxMessages.map(item=>({kind:'message',icon:'statement',label:'رسالة',title:item.title,meta:item.sender,item})),...mediaItems.map(item=>({kind:'media',icon:item.type==='فيديو'?'video':'image',label:'وسائط',title:item.title,meta:item.category,item})),...newsItems.map(item=>({kind:'news',icon:'globe',label:'خبر',title:item.title,meta:item.category,item})),...decisionsData.map(item=>({kind:'decision',icon:'file',label:'قرار',title:item.title,meta:item.entity,item}))]}
function renderGlobalSearch(query){if(!globalSearchInput||!globalSearchResults)return;const term=normalize(query);if(!term){globalSearchResults.hidden=true;globalSearchInput.setAttribute('aria-expanded','false');return}globalSearchMatches=globalSearchEntries().filter(item=>normalize(`${item.title} ${item.meta} ${item.label}`).includes(term)).slice(0,8);globalSearchResults.hidden=false;globalSearchInput.setAttribute('aria-expanded','true');globalSearchResults.innerHTML=globalSearchMatches.length?globalSearchMatches.map((item,index)=>`<button class="global-search-result" type="button" role="option" data-global-result="${index}"><span>${icon(item.icon)}</span><span class="global-search-result-copy"><strong>${item.title}</strong><small>${item.meta}</small></span><em>${item.label}</em>${icon('chevron-left')}</button>`).join(''):'<p>لا توجد نتائج مطابقة. جرّب كلمة أخرى.</p>'}
function openGlobalSearchResult(item){if(!item)return;if(item.kind==='tab')selectTab(item.index);if(item.kind==='document')openDocument(item.item.id);if(item.kind==='message')showDialog(item.title,`<p class="detail-note">${item.meta}</p><p>${item.item.description}</p>`);if(item.kind==='media'){selectTab(1);showDialog(item.title,`<p class="detail-note">${item.meta} · ${item.item.type}</p><p>${item.item.summary}</p>`)}if(item.kind==='news'){newsCategory=item.item.category;selectTab(2);renderSummary()}if(item.kind==='decision'){selectTab(2);showDialog(item.title,`<p class="detail-note">${item.meta}</p><p>${item.item.summary}</p>`)}globalSearchInput.value='';renderGlobalSearch('')}
globalSearchInput?.addEventListener('input',()=>renderGlobalSearch(globalSearchInput.value));
globalSearchInput?.addEventListener('blur',()=>setTimeout(()=>renderGlobalSearch(''),150));
globalSearchResults?.addEventListener('mousedown',e=>e.preventDefault());
globalSearchResults?.addEventListener('click',e=>{const result=e.target.closest('[data-global-result]');if(result)openGlobalSearchResult(globalSearchMatches[Number(result.dataset.globalResult)])});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();globalSearchInput?.focus()}if(e.key==='Escape'&&document.activeElement===globalSearchInput){globalSearchInput.value='';renderGlobalSearch('');globalSearchInput.blur()}});
initializePanels();renderMedia();hydrateIcons();selectTab(2);const compactTabs=matchMedia('(max-width: 760px)');compactTabs.addEventListener('change',()=>selectTab(selected));
const heroSlides=[...document.querySelectorAll('.hero-art')],heroControls=[...document.querySelectorAll('[data-hero-slide]')];let activeHeroSlide=0,heroTimer;function setHeroSlide(index){activeHeroSlide=(index+heroSlides.length)%heroSlides.length;heroSlides.forEach((slide,i)=>slide.classList.toggle('is-active',i===activeHeroSlide));heroControls.forEach((control,i)=>{const active=i===activeHeroSlide;control.classList.toggle('is-active',active);control.setAttribute('aria-selected',String(active))})}function startHeroCarousel(){clearInterval(heroTimer);heroTimer=setInterval(()=>setHeroSlide(activeHeroSlide+1),6000)}heroControls.forEach(control=>control.addEventListener('click',()=>{setHeroSlide(Number(control.dataset.heroSlide));startHeroCarousel()}));const hero=document.querySelector('.hero');hero?.addEventListener('mouseenter',()=>clearInterval(heroTimer));hero?.addEventListener('mouseleave',startHeroCarousel);startHeroCarousel();
